import { Fragment } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import {
  Card,
  CardFooter,
  Button,
  CardBody,
  Row,
  Col,
  Label,
  Input,
  FormFeedback,
} from "reactstrap";
import Select from "react-select";
import { selectThemeColors } from "@utils";
import useBalance from "../../../hooks/use_balance";

const CreateBalance = () => {
  const { createBalanceController, balanceLoadings } = useBalance();

  return (
    <Fragment>
      <Breadcrumbs
        title="Create Balance"
        data={[{ title: "Balances" }, { title: "Create Balance" }]}
      />
      <form onSubmit={createBalanceController.handleSubmit}>
        <Card>
          <CardBody>
            <Row>
              {/* name */}
              <Col className="mt-1" xs="12" sm="6">
                <Label for="name">name</Label>
                <Input
                  value={createBalanceController.values.name}
                  onChange={createBalanceController.handleChange}
                  invalid={
                    createBalanceController.touched.name
                      ? createBalanceController.errors.name
                      : null
                  }
                  name="name"
                  id="name"
                />
                {createBalanceController?.errors?.name && (
                  <FormFeedback>
                    {createBalanceController.errors.name}
                  </FormFeedback>
                )}
              </Col>
              {/* persian_name */}
              <Col className="mt-1" xs="12" sm="6">
                <Label for="persian_name">persian_name</Label>
                <Input
                  value={createBalanceController.values.persian_name}
                  onChange={createBalanceController.handleChange}
                  invalid={
                    createBalanceController.touched.persian_name
                      ? createBalanceController.errors.persian_name
                      : null
                  }
                  name="persian_name"
                  id="persian_name"
                />
                {createBalanceController?.errors?.persian_name && (
                  <FormFeedback>
                    {createBalanceController.errors.persian_name}
                  </FormFeedback>
                )}
              </Col>
              {/* timeframe */}
              <Col className="mt-1" xs="12" sm="6" md="4">
                <Label for="type">timeframe</Label>
                <Select
                  isClearable={false}
                  theme={selectThemeColors}
                  closeMenuOnSelect={true}
                  placeholder="select option"
                  maxMenuHeight={120}
                  options={[
                    {
                      label: "monthly",
                      value: "monthly",
                    },
                    {
                      label: "weekly",
                      value: "weekly",
                    },
                    {
                      label: "daily",
                      value: "daily",
                    },
                    {
                      label: "unlimited",
                      value: "unlimited",
                    },
                  ]}
                  className={`react-select ${
                    createBalanceController.touched.timeframe &&
                    createBalanceController.errors.timeframe
                      ? "form_error"
                      : ""
                  }`}
                  value={createBalanceController.values.timeframe}
                  onChange={(value) => {
                    createBalanceController.setFieldValue("timeframe", value);
                  }}
                  classNamePrefix="select"
                  id="timeframe"
                  name="timeframe"
                />
                {createBalanceController.touched.timeframe &&
                createBalanceController.errors.timeframe ? (
                  <FormFeedback style={{ display: "block" }}>
                    The timeframe field is required.
                  </FormFeedback>
                ) : null}
              </Col>
              {/* usable_from */}
              <Col className="mt-1" xs="12" sm="6" md="4">
                <Label for="usable_from">usable_from</Label>
                <Input
                  value={createBalanceController.values.usable_from}
                  onChange={createBalanceController.handleChange}
                  name="usable_from"
                  id="usable_from"
                />
              </Col>
              {/* usable_till */}
              <Col className="mt-1" xs="12" sm="6" md="4">
                <Label for="usable_till">usable_till</Label>
                <Input
                  value={createBalanceController.values.usable_till}
                  onChange={createBalanceController.handleChange}
                  name="usable_till"
                  id="usable_till"
                />
              </Col>
              {/* type */}
              <Col className="mt-1" xs="12" sm="6" md="4">
                <Label for="type">type</Label>
                <Select
                  isClearable={false}
                  theme={selectThemeColors}
                  closeMenuOnSelect={true}
                  placeholder="select option"
                  maxMenuHeight={120}
                  options={[
                    { label: "data", value: "data" },
                    { label: "video", value: "video" },
                    { label: "voice", value: "voice" },
                  ]}
                  className={`react-select ${
                    createBalanceController.touched.type &&
                    createBalanceController.errors.type
                      ? "form_error"
                      : ""
                  }`}
                  value={createBalanceController.values.type}
                  onChange={(value) => {
                    createBalanceController.setFieldValue("type", value);
                    if (value.value == "video" || value.value == "voice") {
                      createBalanceController.setFieldValue("value", "-");
                    }
                  }}
                  classNamePrefix="select"
                  id="type"
                  name="type"
                />
                {createBalanceController.touched.type &&
                createBalanceController.errors.type ? (
                  <FormFeedback style={{ display: "block" }}>
                    The type field is required.
                  </FormFeedback>
                ) : null}
              </Col>
              {/* value */}
              <Col className="mt-1" xs="12" sm="6" md="8">
                {createBalanceController.values.type.value == "data" ? (
                  <Col xs="12" className="d-flex align-items-center">
                    <Col xs="12" sm="6" style={{ marginRight: 12 }}>
                      <Label for="unit">unit</Label>
                      <Select
                        options={[
                          { label: "GB", value: "GB" },
                          { label: "MB", value: "MB" },
                          { label: "KB", value: "KB" },
                        ]}
                        isClearable={false}
                        theme={selectThemeColors}
                        closeMenuOnSelect={true}
                        placeholder="select option"
                        maxMenuHeight={120}
                        className={"react-select"}
                        value={createBalanceController.values.unit}
                        onChange={(value) => {
                          createBalanceController.setFieldValue("unit", value);
                          createBalanceController.setFieldValue("value", "");
                        }}
                        classNamePrefix="select"
                        id="unit"
                        name="unit"
                      />
                    </Col>
                    <Col xs="12" sm="6">
                      <Label for="value">value</Label>
                      <Input
                        type="number"
                        value={createBalanceController.values.value}
                        onChange={createBalanceController.handleChange}
                        invalid={
                          createBalanceController.touched.value
                            ? createBalanceController.errors.value
                            : null
                        }
                        name="value"
                        id="value"
                      />
                    </Col>
                  </Col>
                ) : null}
                {createBalanceController.values.type.value == "voice" ||
                createBalanceController.values.type.value == "video" ? (
                  <Col xs="12" className="d-flex align-items-center">
                    <Col xs="12" sm="6" style={{ marginRight: 12 }}>
                      <Label for="hours">hours</Label>
                      <Input
                        type="number"
                        value={createBalanceController.values.hours}
                        onChange={createBalanceController.handleChange}
                        name="hours"
                        id="hours"
                      />
                    </Col>
                    <Col xs="12" sm="6">
                      <Label for="minutes">minutes</Label>
                      <Input
                        type="number"
                        max={59}
                        value={createBalanceController.values.minutes}
                        onChange={createBalanceController.handleChange}
                        name="minutes"
                        id="minutes"
                      />
                    </Col>
                  </Col>
                ) : null}
              </Col>
              {/* roaming_balance */}
              <Col sm="12" md="3" className={"mt-2"}>
                <div className="form-switch ps-0">
                  <div className="d-flex">
                    <p
                      className="fw-bold me-auto mb-0"
                      style={{ fontSize: 16 }}
                    >
                      roaming_balance
                    </p>
                    <Input
                      style={{ cursor: "pointer" }}
                      onChange={() =>
                        createBalanceController.setFieldValue(
                          "roaming_balance",
                          !createBalanceController.values.roaming_balance
                        )
                      }
                      checked={createBalanceController?.values.roaming_balance}
                      type="switch"
                    />
                  </div>
                </div>
              </Col>
            </Row>
          </CardBody>
          <CardFooter className="d-flex justify-content-center">
            <Button
              disabled={balanceLoadings.createBalance}
              size="md"
              color={balanceLoadings.createBalance ? "secondary" : "primary"}
            >
              Submit
            </Button>
          </CardFooter>
        </Card>
      </form>
    </Fragment>
  );
};
export default CreateBalance;
